'use strict';

// Optional publications are declared only after their reviewed artifacts exist.
const extraStudies={config:{},collected:null,semantic:null,errors:{},reports:[]};
function studyDate(raw){const d=new Date(raw);return Number.isFinite(d.getTime())?d.toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC':String(raw||'date unreported');}
const collectedState={query:'',context:'all',origin:'all',overlap:'all',page:1,sort:'title',matrix:'whole',matrixRowBlock:0,matrixColumnBlock:0,keyword:''};

async function loadAdditionalStudies(){
  extraStudies.config={};extraStudies.collected=null;extraStudies.semantic=null;extraStudies.errors={};extraStudies.reports=[];
  try{extraStudies.config=JSON.parse($('#optional-studies')?.textContent||'{}');}
  catch{extraStudies.errors.config='Optional study configuration could not be read.';return;}
  const allowed={collected_audio:'collected-audio-analysis.json',semantic_pilot:'semantic-pilot.json'};
  const requests=Object.entries(allowed).filter(([key])=>extraStudies.config[key]).map(async([key,path])=>{
    const target=key==='collected_audio'?'collected':'semantic';
    try{
      if(extraStudies.config[key]!==path)throw Error('The declared local study path is not supported.');
      const d=await getJson(path);
      if(d.schema_version!==1)throw Error('The declared study schema is not supported.');
      if(target==='collected'&&(!Array.isArray(d.documents)||!Array.isArray(d.coverage?.groups)))throw Error('Collected-audio coverage and source records are missing.');
      extraStudies[target]=d;
    }catch(e){extraStudies.errors[target]=e.message;}
  });
  const report=extraStudies.config.report||{};
  for(const [key,path] of Object.entries({pdf:'report/paper.pdf',markdown:'report/paper.md',source:'report/source.zip'})){
    if(report[key]!==path)continue;
    requests.push((async()=>{try{const response=await fetch(path,{method:'HEAD',cache:'no-cache'});if(response.ok)extraStudies.reports.push({key,path});else extraStudies.errors.report='A declared report asset is currently unavailable.';}catch{extraStudies.errors.report='The report assets could not be checked.';}})());
  }
  await Promise.allSettled(requests);
}

function reportLinks(){
  const labels={pdf:'Read the core-studies paper (PDF)',markdown:'Read the core-studies paper (Markdown)',source:'Download LaTeX / Overleaf sources (ZIP)'};return extraStudies.reports.map(r=>`<a href="${esc(r.path)}" ${r.key==='pdf'?'target="_blank" rel="noopener"':r.key==='source'?'download':''}>${labels[r.key]}</a>`).join('');
}

function additionalStudyNav(){
  const links=[['main','Joint source-context study'],['named-label-pilot','Written-message pilot']];
  if(extraStudies.collected||extraStudies.errors.collected)links.push(['collected-audio-study','Collected-audio text study']);
  if(extraStudies.semantic||extraStudies.errors.semantic)links.push(['semantic-pilot-study','Semantic message pilot']);
  if(links.length===2&&!extraStudies.reports.length&&!extraStudies.errors.config)return '';
  return `<nav class="study-jumps" aria-label="Text analysis studies">${links.map(([id,label])=>`<button type="button" class="secondary" data-study-target="${id}">${esc(label)}</button>`).join('')}${reportLinks()}</nav>${extraStudies.errors.config?`<p class="empty">${esc(extraStudies.errors.config)}</p>`:''}`;
}

function collectedDocument(id){return arr(extraStudies.collected?.documents).find(d=>d.source_id===id);}
function collectedGroup(id){return arr(extraStudies.collected?.coverage?.groups).find(g=>g.id===id);}
function collectedModelIds(){return new Set(arr(extraStudies.collected?.lexical?.source_ids));}
function selectedCollectedDocs(){
  const q=collectedState.query.trim().toLowerCase();
  return arr(extraStudies.collected?.documents).filter(d=>
    (collectedState.context==='all'||d.group_id===collectedState.context)&&
    (collectedState.origin==='all'||d.text_origin===collectedState.origin)&&
    (collectedState.overlap==='all'||(collectedState.overlap==='previous'?d.in_existing_frozen_models===true:d.in_existing_frozen_models!==true))&&
    (!q||[d.source_id,d.publication_id,d.title,d.publisher,d.group_label,d.text_origin].join(' ').toLowerCase().includes(q))
  ).sort((a,b)=>collectedState.sort==='words'?b.words-a.words:collectedState.sort==='context'?String(a.group_label).localeCompare(String(b.group_label))||String(a.title).localeCompare(String(b.title)):String(a.title).localeCompare(String(b.title)));
}

function collectedSourceTable(){
  const rows=selectedCollectedDocs(),modelIds=collectedModelIds(),pages=Math.max(1,Math.ceil(rows.length/12));
  collectedState.page=Math.min(collectedState.page,pages);
  return `<div class="result-summary"><p><strong>${num(rows.length)}</strong> selected transcript editions match. Prior-study overlap, text origin and speaker uncertainty stay attached to every record.</p><button class="secondary" type="button" id="export-collected-sources">Export filtered transcript metadata</button></div>
    <div class="table-wrap" role="region" tabindex="0" aria-label="Collected audio transcript source explorer"><table class="register-table"><thead><tr><th>Transcript edition</th><th>Publisher context / text origin</th><th>Words / audio minutes</th><th>Analysis and previous-study overlap</th></tr></thead><tbody>
    ${rows.slice((collectedState.page-1)*12,collectedState.page*12).map(d=>`<tr><th scope="row"><button type="button" class="text-button record-label" data-collected-source="${esc(d.source_id)}">${esc(d.title||d.source_id)}</button><small>${esc(d.source_id)}</small></th><td>${esc(d.group_label||name(collectedGroup(d.group_id)))}<small>${esc(human(d.text_origin))}<br>Speaker roles: unknown</small></td><td>${num(d.words)}<small>${num(finite(d.duration_seconds)?d.duration_seconds/60:null,2)} audio minutes</small></td><td>${modelIds.has(d.source_id)?'Included lexical model unit':'Outside lexical fit'}<small>${d.in_existing_frozen_models===true?'Exact caption edition reused from an earlier model':'No exact caption-edition overlap established'}<br>${esc(human(d.new_text_status||'text novelty unreported'))}</small></td></tr>`).join('')||'<tr><td colspan="4">No transcript editions match these filters.</td></tr>'}
    </tbody></table></div><div class="pager collected-pager"><button type="button" class="secondary" data-collected-page="${collectedState.page-1}" ${collectedState.page<=1?'disabled':''}>Previous</button><span>Page ${collectedState.page} of ${pages}</span><button type="button" class="secondary" data-collected-page="${collectedState.page+1}" ${collectedState.page>=pages?'disabled':''}>Next</button></div>`;
}

function collectedSimilarityMatrix(){
  const d=extraStudies.collected,l=d.lexical||{},window=collectedState.matrix==='window';
  const ids=arr(window?l.window_300_source_ids:l.source_ids),values=arr(window?l.window_300_matrix:l.matrix),reference=arr(l.source_ids);
  if(l.status!=='fitted'||!ids.length)return '<p class="empty">No eligible matrix is available for this text length. Short texts are excluded from the window view, not padded.</p>';
  const bounded=ids.length>40,blockSize=bounded?20:ids.length,blockCount=Math.ceil(ids.length/blockSize);
  collectedState.matrixRowBlock=Math.max(0,Math.min(Math.floor(Number(collectedState.matrixRowBlock)||0),blockCount-1));
  collectedState.matrixColumnBlock=Math.max(0,Math.min(Math.floor(Number(collectedState.matrixColumnBlock)||0),blockCount-1));
  const rowStart=bounded?collectedState.matrixRowBlock*blockSize:0,columnStart=bounded?collectedState.matrixColumnBlock*blockSize:0;
  const rowIds=ids.slice(rowStart,rowStart+blockSize),columnIds=ids.slice(columnStart,columnStart+blockSize),ordinals=new Map(reference.map((id,i)=>[id,i+1]));
  const blockOptions=selected=>Array.from({length:blockCount},(_,i)=>`<option value="${i}" ${selected===i?'selected':''}>${i*blockSize+1}–${Math.min(ids.length,(i+1)*blockSize)}</option>`).join('');
  const controls=bounded?`<div class="toolbar matrix-block-controls"><label>Visible row positions<select id="collected-matrix-rows">${blockOptions(collectedState.matrixRowBlock)}</select></label><label>Visible column positions<select id="collected-matrix-columns">${blockOptions(collectedState.matrixColumnBlock)}</select></label></div><p class="caption matrix-subset-summary">Showing row positions <strong>${rowStart+1}–${rowStart+rowIds.length}</strong> and column positions <strong>${columnStart+1}–${columnStart+columnIds.length}</strong> of <strong>${num(ids.length)}</strong> eligible source-text units (${rowIds.length} × ${columnIds.length} visible cells). Positions index the current whole/window set; table source numbers retain the full-study source order. The CSV export above includes every source pair; the analysis JSON includes both complete matrices.</p>`:'';
  return `<p class="caption"><strong>${num(ids.length)}</strong> source-text units. Diagonal values compare a text with itself; off-diagonal cells are cosine scores, not agreement probabilities. Column numbers refer to the same source order shown at the left. ${window?esc(l.window_rule):esc(l.scope)}</p>${controls}<div class="table-wrap" role="region" tabindex="0" aria-label="Collected text TF-IDF cosine matrix"><table class="collected-matrix"><thead><tr><th>Source-text unit</th>${columnIds.map(id=>`<th>${ordinals.get(id)}</th>`).join('')}</tr></thead><tbody>${rowIds.map((id,i)=>`<tr><th scope="row"><button type="button" class="text-button" data-collected-source="${esc(id)}">${ordinals.get(id)}. ${esc(collectedDocument(id)?.title||id)}</button></th>${columnIds.map((_,j)=>`<td>${num(values[rowStart+i]?.[columnStart+j],3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function collectedKeywordView(){
  const rows=arr(extraStudies.collected?.keywords),keys=unique(rows.flatMap(r=>Object.keys(r.rates||{}))).sort();
  if(!keys.includes(collectedState.keyword))collectedState.keyword=keys[0]||'';
  if(!keys.length)return '<p class="empty">No keyword counts are available in this study snapshot.</p>';
  const sorted=rows.filter(r=>finite(r.rates?.[collectedState.keyword]?.per_1000_tokens)).sort((a,b)=>b.rates[collectedState.keyword].per_1000_tokens-a.rates[collectedState.keyword].per_1000_tokens);
  return `<label class="keyword-selector">Keyword dictionary group<select id="collected-keyword">${keys.map(k=>`<option value="${esc(k)}" ${k===collectedState.keyword?'selected':''}>${esc(human(k))}</option>`).join('')}</select></label><p class="caption">Released word-form counts and rates for each transcript edition. Dictionary matches can be negated, quoted, polysemous or recognition errors; they do not establish beliefs, speaker identity or answer accuracy.</p><div class="table-wrap" role="region" tabindex="0" aria-label="Collected transcript keyword rates"><table class="register-table"><thead><tr><th>Transcript edition</th><th>Source context</th><th>Matches</th><th>Per 1,000 analysis tokens</th></tr></thead><tbody>${sorted.map(r=>{const doc=collectedDocument(r.source_id),rate=r.rates[collectedState.keyword];return `<tr><th scope="row"><button class="text-button" type="button" data-collected-source="${esc(r.source_id)}">${esc(doc?.title||r.source_id)}</button></th><td>${esc(doc?.group_label||r.group_id)}</td><td>${num(rate.mentions)}</td><td>${num(rate.per_1000_tokens,3)}</td></tr>`;}).join('')}</tbody></table></div>${extraStudies.collected.keyword_dictionaries?`<details><summary>Inspect the exact keyword dictionary</summary><p class="caption">${esc(extraStudies.collected.keyword_scope||'Dictionary terms define extraction; they do not validate a semantic category.')}</p>${facts(Object.entries(extraStudies.collected.keyword_dictionaries).map(([key,terms])=>[human(key),arr(terms).join(', ')]))}<p class="hash">Dictionary helper SHA-256: ${esc(extraStudies.collected.keyword_dictionary_helper_sha256)}</p></details>`:''}`;
}

function collectedAudioView(){
  const d=extraStudies.collected;
  if(!d)return extraStudies.errors.collected?`<section class="section" id="collected-audio-study" tabindex="-1"><h2>Collected-audio study unavailable</h2><p class="empty">${esc(extraStudies.errors.collected)} Earlier studies remain available. No replacement observations were generated.</p></section>`:'';
  const c=d.coverage||{},groups=arr(c.groups),modelIds=collectedModelIds(),docs=arr(d.documents),reused=groups.reduce((n,g)=>n+(g.previously_modeled_caption_units||0),0),newAsr=groups.reduce((n,g)=>n+(g.new_local_asr_units||0),0);
  return `<section class="section" id="collected-audio-study" tabindex="-1"><span class="eyebrow">SEPARATE COLLECTED-AUDIO TEXT SNAPSHOT</span><div class="section-head"><h2>What the downloaded recordings add.</h2><p>This analysis follows the frozen acquisition and recognition inputs listed below. Its cutoff can differ from the dashboard’s separately dated acquisition-progress snapshot, and it does not update the earlier joint or written-message model fits.</p></div>
  <div class="scope-note"><p><strong>Study generated ${esc(studyDate(d.generated_at))}.</strong> Collection status at its cutoff: ${esc(human(c.collection_status_at_snapshot))}. Its ${num(c.retained_audio_publications)} retained audio publications belong to a finite ${num(c.finite_publisher_frame)}-entry publisher frame; total channel uploads remain unknown.</p><p><strong>${num(newAsr)} local ASR editions and ${num(reused)} previously modeled caption editions</strong> contribute to this snapshot. Reused caption text does not become a new independent observation because its associated audio was downloaded. Speaker roles and utterance-level claimed entities remain unknown.</p></div>
  <div class="metrics"><div><b>${num(c.retained_audio_publications)}</b><span>audio publications at this study cutoff</span></div><div><b>${num(c.selected_text_units)}</b><span>selected transcript editions</span></div><div><b>${num(c.lexical_model_units)}</b><span>lexical model units</span></div><div><b>${num(c.words)}</b><span>words across selected editions</span></div></div>
  <div class="table-wrap" role="region" tabindex="0" aria-label="Downloaded transcribed and analyzed counts by publisher context"><table class="register-table"><thead><tr><th>Publisher / recording context</th><th>Audio retained</th><th>Selected text editions</th><th>Lexical units</th><th>New local ASR</th><th>Reused prior-model captions</th><th>Selected words</th></tr></thead><tbody>${groups.map(g=>`<tr><th scope="row">${esc(g.label||g.id)}</th><td>${num(g.retained_audio_publications)}</td><td>${num(g.selected_text_units)}</td><td>${num(docs.filter(x=>x.group_id===g.id&&modelIds.has(x.source_id)).length)}</td><td>${num(g.new_local_asr_units)}</td><td>${num(g.previously_modeled_caption_units)}</td><td>${num(g.words)}</td></tr>`).join('')}</tbody></table></div><p class="caption">Publisher contexts can contain hosts, guests, introductions and attributed channeling. None of these counts establishes a unique human speaker, claimed being, or independent original performance.</p>
  <section class="section"><div class="section-head"><h3>Whole transcript versus a fixed-length window</h3><p>TF-IDF captures shared vocabulary in recognized or publisher-captioned text. The 300-token view reuses the whole-text vocabulary and IDF; shorter sources are excluded from that view. Each matrix retains its actual source set.</p></div><div class="toolbar"><label>Text length<select id="collected-matrix-mode"><option value="whole" ${collectedState.matrix==='whole'?'selected':''}>Whole transcript</option><option value="window" ${collectedState.matrix==='window'?'selected':''}>Centered 300-token window</option></select></label><button type="button" class="secondary" id="export-collected-similarities">Export source-pair similarities</button></div><div id="collected-matrix-results">${collectedSimilarityMatrix()}</div></section>
  <section class="section"><div class="section-head"><h3>Exploratory topic factors and clusters</h3><p>Topic factors and clusters describe this selected text set. Different publishers, recognition editions, lengths and unequal counts remain confounded; the outputs do not identify civilizations or teachings.</p></div>${d.topics?.status==='exploratory_fit'?`<div class="topics">${arr(d.topics.components).map(t=>`<article class="topic"><h3>Collected factor ${esc(t.id)}</h3><div class="chips">${arr(t.terms).map(term=>`<span>${esc(term)}</span>`).join('')}</div></article>`).join('')}</div><p class="table-note">Up to three exploratory factors are displayed when at least five eligible documents are available. This is a display rule, not an optimal topic-count estimate. Clustering k=${num(d.clusters?.k)}, cosine silhouette=${num(d.clusters?.silhouette,4)}. Cluster assignments appear in each source inspector.</p>`:`<p class="empty">${num(d.topics?.minimum_documents||5)} eligible texts are required for this exploratory topic display. This snapshot does not meet that threshold.</p>`}</section>
  <section class="section"><h3>Keyword-based extraction</h3><div id="collected-keyword-results">${collectedKeywordView()}</div></section>
  ${arr(d.figures).filter(f=>String(f.file||'').endsWith('.svg')).map(f=>figure({...f,file:'collected-audio-figures/'+f.file})).join('')}
  <section class="section"><div class="section-head"><h3>Machine text and the publisher’s written edition</h3><p>Where an audio publication also links a written message, ordered token overlap measures how the editions resemble each other. This is not word error rate or recognition accuracy: introductions, omitted passages, paraphrase and recognition errors have not been disentangled.</p></div>${arr(d.paired_written_editions).length?`<div class="table-wrap" role="region" tabindex="0" aria-label="Written and recognized edition overlap"><table class="register-table"><thead><tr><th>Recording text edition</th><th>Recognized words</th><th>Linked written words</th><th>Ordered-token ratio</th><th>Alignment verified</th></tr></thead><tbody>${arr(d.paired_written_editions).map(r=>`<tr><th scope="row"><button type="button" class="text-button" data-collected-source="${esc(r.source_id)}">${esc(collectedDocument(r.source_id)?.title||r.source_id)}</button></th><td>${num(r.text_words)}</td><td>${num(r.linked_written_words)}</td><td>${num(r.token_sequence_ratio,4)}</td><td>${r.audio_alignment_verified===true?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No linked written/audio edition comparison is present in this snapshot.</p>'}</section>
  <section class="section"><div class="section-head"><h3>Inspect every selected transcript edition</h3><p>${num(d.qa?.unverified_punctuation_turns)} punctuation-containing turns remain unverified question candidates; ${num(d.qa?.identified_answers)} identified answers are reported. Machine segments are not speaker-diarized turns.</p></div><form class="toolbar"><label class="search">Search transcripts<input id="collected-query" type="search" value="${esc(collectedState.query)}" placeholder="Title, source ID or publisher"></label><label>Publisher context<select id="collected-context"><option value="all">All contexts</option>${groups.map(g=>`<option value="${esc(g.id)}" ${collectedState.context===g.id?'selected':''}>${esc(g.label||g.id)}</option>`).join('')}</select></label><label>Text origin<select id="collected-origin"><option value="all">All text origins</option>${unique(docs.map(x=>x.text_origin)).sort().map(o=>`<option value="${esc(o)}" ${collectedState.origin===o?'selected':''}>${esc(human(o))}</option>`).join('')}</select></label><label>Previous-study overlap<select id="collected-overlap"><option value="all">All editions</option><option value="previous" ${collectedState.overlap==='previous'?'selected':''}>Exact prior-model caption matches</option><option value="no_exact" ${collectedState.overlap==='no_exact'?'selected':''}>No exact prior-caption match</option></select></label><label>Sort editions<select id="collected-sort"><option value="title" ${collectedState.sort==='title'?'selected':''}>Title</option><option value="context" ${collectedState.sort==='context'?'selected':''}>Publisher context</option><option value="words" ${collectedState.sort==='words'?'selected':''}>Word count, high to low</option></select></label><button type="button" id="clear-collected" class="secondary">Clear transcript filters</button></form><div id="collected-source-results">${collectedSourceTable()}</div></section>
  <details><summary>Snapshot bindings and dispositions</summary><p class="caption">These named private input snapshots define the study cutoff. Their hashes permit an audit; they are not download links to raw transcripts.</p>${facts(arr(d.snapshot_bindings).map(x=>[x.snapshot_file,x.sha256]))}<pre>${esc(JSON.stringify(d.excluded_and_aliases||[],null,2))}</pre></details><ul class="limitations">${arr(d.limitations).map(l=>`<li>${esc(text(l))}</li>`).join('')}</ul><div class="downloads"><a href="collected-audio-analysis.json" download>Download collected-audio analysis JSON</a>${reportLinks()}</div></section>`;
}

function inspectCollected(id,trigger){
  const d=collectedDocument(id);if(!d)return;
  const modelIds=collectedModelIds(),cluster=arr(extraStudies.collected.clusters?.assignments).find(x=>x.source_id===id),terms=arr(extraStudies.collected.lexical?.top_terms).find(x=>x.source_id===id),paired=arr(extraStudies.collected.paired_written_editions).find(x=>x.source_id===id);
  lastTrigger=trigger||document.activeElement;
  $('#record-detail').innerHTML=`<h2 id="record-title">${esc(d.title||d.source_id)}</h2><p>${esc(d.group_label||d.group_id)} · ${esc(human(d.text_origin))}</p><p><strong>Unknown speaker roles; no utterance-level claimed entity is assigned.</strong> A publisher title can identify the episode’s subject without identifying every voice or statement.</p>${facts([['Source ID',d.source_id],['Publication ID',d.publication_id],['Publication date',d.publication_date||'Unknown'],['Publication date status',human(d.date_status)],['Raw publisher date',d.publisher_date_raw||d.raw_publication_date],['Words',d.words],['Audio seconds',d.duration_seconds],['Source role',human(d.source_role)],['Text novelty / reuse',human(d.new_text_status)],['Previous model overlap',d.prior_model_overlap],['Previous study model unit',d.previous_study_model_unit_id],['Lexical model disposition',modelIds.has(id)?'Included':'Outside fit'],['Exploratory cluster',cluster?.cluster],['Recognition accuracy verified',d.human_accuracy_verified===true?'Yes':'No'],['Audio/text alignment verified',d.audio_text_alignment_verified===true?'Yes':'No'],['Retained audio SHA-256',d.retained_audio_sha256],['Transcript artifact SHA-256',d.text_artifact_sha256],['Exact original family',d.exact_original_family_id]])}<p>${link(d.source_url,'Open publisher episode or source page')}</p>${terms?`<h3>Highest TF-IDF terms</h3><div class="chips">${arr(terms.terms).map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:''}<h3>Timestamp and edition checks</h3><pre>${esc(JSON.stringify({timestamp_normalization:d.timestamp_normalization,timestamp_quality:d.timestamp_quality,paired_written_edition:paired||null},null,2))}</pre>`;
  $('#record-dialog').showModal();$('#close-record').focus();
}

function semanticPilotView(){
  const d=extraStudies.semantic;
  if(!d)return extraStudies.errors.semantic?`<section class="section" id="semantic-pilot-study" tabindex="-1"><h2>Semantic pilot unavailable</h2><p class="empty">${esc(extraStudies.errors.semantic)}</p></section>`:'';
  const totals=d.totals||{},docs=arr(d.documents),lookup=id=>docs.find(x=>x.source_id===id),reviews=arr(d.reading?.reviews||d.reading_reviews||d.semantic_reading?.reviews),reviewFor=p=>reviews.find(r=>(r.source_id===p.source&&r.target_id===p.target)||(r.source_id===p.target&&r.target_id===p.source));
  const same=arr(d.pairs).filter(p=>p.comparison_kind==='same_label_cross_medium'),named=same.filter(p=>p.comparison_level==='named_label').length;
  return `<section class="section" id="semantic-pilot-study" tabindex="-1"><span class="eyebrow">SEPARATE EMBEDDING ANALYSIS · SAME WRITTEN-MESSAGE PILOT</span><div class="section-head"><h2>Does the pattern persist beyond shared words?</h2><p>This separately computed analysis uses a pretrained embedding model to represent the written-message pilot, with complete chunk coverage, a 300-token window control and a pooling sensitivity. It does not expand the number of independent sources.</p></div><div class="scope-note"><p><strong>Embedding cosine is model-dependent language proximity.</strong> It does not measure doctrinal agreement, the reality of a named being, common origin or equivalent answers. Shared-label comparisons contain ${num(named)} named-label pairs and ${num(same.length-named)} broad-civilization-label pairs; those scopes remain different.</p><p>Study generated ${esc(studyDate(d.generated_at))}. Model: ${esc(d.model?.model)}; revision ${esc(d.model?.revision)}. Pair rows share documents and are dependent; no inferential test or agreement probability is reported.</p></div><div class="metrics"><div><b>${num(totals.documents)}</b><span>same pilot message documents</span></div><div><b>${num(totals.full_wordpieces)}</b><span>full-text wordpieces encoded</span></div><div><b>${num(totals.full_chunks)}</b><span>full-text chunks encoded</span></div><div><b>${num(totals.truncated_wordpieces)}</b><span>truncated wordpieces reported</span></div></div><div class="table-wrap" role="region" tabindex="0" aria-label="Semantic pair category comparison"><table class="register-table semantic-summary"><thead><tr><th>Pair category</th><th>Dependent pairs</th><th>Whole-text mean cosine</th><th>300-token mean cosine</th><th>Equal-chunk mean cosine</th></tr></thead><tbody>${arr(d.pair_summary).map(r=>`<tr><th scope="row">${esc(human(r.kind))}</th><td>${num(r.pairs)}</td><td>${num(r.full_mean,4)}</td><td>${num(r.window_300_mean,4)}</td><td>${num(r.equal_chunk_mean,4)}</td></tr>`).join('')}</tbody></table></div><p class="caption">Window coverage: ${num(totals.window_wordpieces)} wordpieces across ${num(totals.window_chunks)} chunks. Pooling sensitivity changes how chunks contribute; it does not create a new independent sample.</p>${semanticLabelSummary(d)}${arr(d.figures).filter(f=>String(f.file||'').endsWith('.svg')).map(f=>figure({...f,file:'semantic-figures/'+f.file})).join('')}<section class="section"><div class="section-head"><h3>Nearest pairs, with their source contexts</h3><p>High retrieval proximity is a reading prompt. Open the original message and inspect differences in recommendations, framing and boundaries before interpreting the score.</p></div><div class="table-wrap" role="region" tabindex="0" aria-label="Semantic nearest pair reading leads"><table class="register-table"><thead><tr><th>Source pair</th><th>Comparison scope / review</th><th>Full semantic cosine</th><th>300-token semantic cosine</th><th>Strict lexical cosine</th></tr></thead><tbody>${arr(d.reading_leads).map(p=>{const a=lookup(p.source),b=lookup(p.target),review=reviewFor(p);return `<tr><th scope="row">${link(a?.source_url,(a?.medium||p.source_medium)+' · '+(a?.title||p.source))}<small>${link(b?.source_url,(b?.medium||p.target_medium)+' · '+(b?.title||p.target))}</small></th><td>${esc(human(p.comparison_level))}<small>${review?esc(human(review.status)):'Reading review not attached to this release'}</small></td><td>${num(p.semantic_cosine,4)}</td><td>${num(p.window_300_cosine,4)}</td><td>${num(p.strict_lexical_cosine,4)}</td></tr>`;}).join('')}</tbody></table></div></section>${reviews.map(r=>{const a=lookup(r.source_id),b=lookup(r.target_id);return `<article class="comparison-row semantic-reading"><h3>${esc(a?.medium||r.source_id)} / ${esc(b?.medium||r.target_id)}</h3><p class="caption">${esc(human(r.comparison_level))} · ${esc(human(r.status))}</p><p><strong>Shared theme:</strong> ${esc(r.shared_theme)}</p><p><strong>${esc(a?.medium||'First source')}:</strong> ${esc(r.source_paraphrase)}</p><p><strong>${esc(b?.medium||'Second source')}:</strong> ${esc(r.target_paraphrase)}</p><p><strong>Difference:</strong> ${esc(r.difference)}</p><p><strong>Counterpoint:</strong> ${esc(r.counterpoint)}</p><p><strong>Assessment:</strong> ${esc(r.equivalence_assessment)}</p><p class="caption">Source locators: ${esc(text(r.source_location))}; ${esc(text(r.target_location))}.</p><div class="analysis-links">${link(r.source_url||a?.source_url,a?.title||r.source_id)}${link(r.target_url||b?.source_url,b?.title||r.target_id)}</div></article>`;}).join('')}<details><summary>Model, chunk processing and source coverage</summary><p class="caption">The recorded model revision, content hashes, token coverage and processing settings make this embedding run reproducible. Complete token coverage does not guarantee preserved discourse structure or correct interpretation.</p><pre>${esc(JSON.stringify({model:d.model,processing:d.processing,totals:d.totals,coverage:d.coverage,window_coverage:d.window_coverage,reading_scope:d.reading?.review_scope},null,2))}</pre></details><ul class="limitations">${arr(d.limitations).map(l=>`<li>${esc(text(l))}</li>`).join('')}</ul><div class="downloads"><a href="semantic-pilot.json" download>Download semantic-pilot analysis JSON</a>${reportLinks()}</div></section>`;
}

document.addEventListener('input',e=>{if(e.target.id==='collected-query'){collectedState.query=e.target.value;collectedState.page=1;$('#collected-source-results').innerHTML=collectedSourceTable();announce(selectedCollectedDocs().length+' selected transcript editions match.');}});
document.addEventListener('change',e=>{
  const map={'collected-context':'context','collected-origin':'origin','collected-overlap':'overlap','collected-sort':'sort'};
  if(map[e.target.id]){collectedState[map[e.target.id]]=e.target.value;collectedState.page=1;$('#collected-source-results').innerHTML=collectedSourceTable();announce(selectedCollectedDocs().length+' selected transcript editions match.');}
  if(e.target.id==='collected-matrix-mode'){collectedState.matrix=e.target.value;collectedState.matrixRowBlock=0;collectedState.matrixColumnBlock=0;$('#collected-matrix-results').innerHTML=collectedSimilarityMatrix();announce('Transcript similarity matrix changed to '+(e.target.value==='window'?'300-token windows':'whole transcripts')+'.');}
  if(e.target.id==='collected-matrix-rows'||e.target.id==='collected-matrix-columns'){
    const control=e.target.id;collectedState[control==='collected-matrix-rows'?'matrixRowBlock':'matrixColumnBlock']=Number(e.target.value);
    $('#collected-matrix-results').innerHTML=collectedSimilarityMatrix();document.getElementById(control)?.focus({preventScroll:true});announce($('.matrix-subset-summary')?.textContent||'Transcript similarity matrix updated.');
  }
  if(e.target.id==='collected-keyword'){collectedState.keyword=e.target.value;$('#collected-keyword-results').innerHTML=collectedKeywordView();$('#collected-keyword').focus();announce(human(collectedState.keyword)+' keyword rates displayed.');}
});
document.addEventListener('click',e=>{
  const jump=e.target.closest('[data-study-target]');if(jump){const target=document.getElementById(jump.dataset.studyTarget);if(target){if(!target.hasAttribute('tabindex'))target.tabIndex=-1;target.focus({preventScroll:true});target.scrollIntoView({block:'start'});}return;}
  const source=e.target.closest('[data-collected-source]');if(source){inspectCollected(source.dataset.collectedSource,source);return;}
  const page=e.target.closest('[data-collected-page]');if(page&&!page.disabled){collectedState.page=Number(page.dataset.collectedPage);$('#collected-source-results').innerHTML=collectedSourceTable();($('#collected-source-results .pager button:last-child:not(:disabled)')||$('#collected-source-results .pager button:first-child:not(:disabled)'))?.focus();return;}
  if(e.target.id==='clear-collected'){Object.assign(collectedState,{query:'',context:'all',origin:'all',overlap:'all',page:1,sort:'title'});$('#collected-audio-study').outerHTML=collectedAudioView();$('#collected-query').focus();announce('Transcript source filters cleared.');}
  if(e.target.id==='export-collected-sources'){const keys=['source_id','publication_id','title','publisher','group_id','group_label','text_origin','words','duration_seconds','source_role','source_url','in_existing_frozen_models','new_text_status','human_accuracy_verified','audio_text_alignment_verified','retained_audio_sha256','text_artifact_sha256'];exportCsv('collected-transcript-editions.csv',keys,selectedCollectedDocs().map(d=>keys.map(k=>d[k])));}
  if(e.target.id==='export-collected-similarities'){
    const l=extraStudies.collected.lexical,ids=arr(l.source_ids),windowPositions=new Map(arr(l.window_300_source_ids).map((id,i)=>[id,i])),rows=[];
    for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++){const wi=windowPositions.get(ids[i]),wj=windowPositions.get(ids[j]);rows.push([ids[i],ids[j],l.matrix[i]?.[j],wi!==undefined&&wj!==undefined?l.window_300_matrix[wi]?.[wj]:null]);}
    exportCsv('collected-transcript-similarities.csv',['source_id','comparison_source_id','whole_text_cosine','window_300_cosine'],rows);
  }
});

function semanticLabelSummary(d){return arr(d.label_summary).length?`<details><summary>Compare individual written labels and broad civilization labels</summary><p class="caption">These are selected message pairs, often with one pair per named figure. The group labels describe comparison scope and do not establish a common speaker or tradition.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Semantic comparison by claimed label"><table class="register-table semantic-label-summary"><thead><tr><th>Comparison label</th><th>Scope</th><th>Pairs</th><th>Whole-text mean</th><th>300-token mean</th><th>Equal-chunk mean</th></tr></thead><tbody>${arr(d.label_summary).map(r=>`<tr><th scope="row">${esc(human(r.comparison_label))}</th><td>${esc(human(r.comparison_level))}</td><td>${num(r.pairs)}</td><td>${num(r.full_mean,4)}</td><td>${num(r.window_300_mean,4)}</td><td>${num(r.equal_chunk_mean,4)}</td></tr>`).join('')}</tbody></table></div></details>`:'';}
